arguments.file_text:
@page "/chat"
@using sv_6163bc11942b4a839de4c49b5cb88976.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar
        Channels="_channels"
        ActiveChannelId="_activeChannelId"
        OnChannelSelected="HandleChannelSelected" />

    <div class="chat-main @(_threadOpen ? "thread-visible" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea
                ChannelName="@_activeChannel.Name"
                ChannelDescription="@_activeChannel.Description"
                Messages="_messages"
                ThreadSummaries="_threadSummaries"
                IsLoadingMore="_isLoadingMore"
                OnOpenThread="HandleOpenThread"
                OnReact="HandleReact"
                OnSendMessage="HandleSendMessage"
                OnLoadMore="HandleLoadMore" />
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <ThreadPanel
            RootMessage="_threadRootMessage"
            Replies="_threadReplies"
            OnClose="HandleCloseThread"
            OnSendReply="HandleSendReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<Message> _threadReplies = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private Channel? _activeChannel;
    private int _activeChannelId;
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private bool _isLoadingMore;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        await SelectChannel(channelId);
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = [];
        _threadOpen = false;
        _threadRootMessage = null;
        _hasMoreMessages = true;

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        BuildThreadSummaries();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task HandleLoadMore()
    {
        if (_isLoadingMore || !_hasMoreMessages) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        if (older.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        _messages.InsertRange(0, older);
        BuildThreadSummaries();
        _isLoadingMore = false;
    }

    private async Task HandleOpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private async Task HandleCloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
        await Task.CompletedTask;
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reaction
        var refreshed = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
        _messages = refreshed;
    }

    private async Task HandleSendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(sent);
    }

    private async Task HandleSendReply(string content)
    {
        if (_threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary
        _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(
            _threadRootMessage.Id,
            _threadReplies.Count,
            reply.SentAt);
    }

    private void BuildThreadSummaries()
    {
        // Identify messages that are thread starters (have replies referencing them)
        var replyGroups = _messages
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        _threadSummaries = replyGroups.ToDictionary(
            g => g.Key,
            g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)));
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #8e9297;
    border-bottom: 1px solid #202225;
}

.channel-list {
    list-style: none;
    padding: 8px 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    border-radius: 4px;
    margin: 2px 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #72767d;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.chat-main.thread-visible {
    max-width: 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #36393f;
    color: #dcddde;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.message-area-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Message Item */
.message-item {
    padding: 8px 12px;
    border-radius: 4px;
    position: relative;
    margin-bottom: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dcddde;
}

.message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: default;
}

.thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 4px;
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    transition: background 0.1s, color 0.1s;
}

.action-btn:hover {
    background: #4f545c;
    color: #fff;
}

